 function undo(){if(!history||busy)return;history.undo();page=clone(history.current);dirty=history.dirty;canUndo=history.past.length>0;canRedo=history.future.length>0;emitDirty();schedulePreview()}
 function redo(){if(!history||busy)return;history.redo();page=clone(history.current);dirty=history.dirty;canUndo=history.past.length>0;canRedo=history.future.length>0;emitDirty();schedulePreview()}
 async function addPage(){guard(()=>{void(async()=>{busy=true;try{const out=await request<PageResponse>(`${initial.api}/pages`,'POST',{layout_id:''});await refreshPages();install(out);tray='layouts'}catch(e){fail(e)}finally{busy=false}})()})}
 async function reorder(delta:number){if(!page)return;const ids=pages.map(p=>p.id),i=ids.indexOf(page.id),j=i+delta;if(j<0||j>=ids.length)return;[ids[i],ids[j]]=[ids[j],ids[i]];busy=true;try{const out=await request<{pages:typeof pages}>(`${initial.api}/pages/reorder`,'POST',{ids});pages=out.pages;await load(page.id)}catch(e){fail(e)}finally{busy=false}}
