 async function keep(){if(!page||!activeJob||busy)return;if(dirty&&!await save())return;busy=true;try{install(await request<PageResponse>(`${pageAPI()}/jobs/${activeJob.id}/apply`,'POST',{index:candidateIndex}));tray='properties';tool='select';activeJob=null;jobID='';candidates=[];const url=new URL(location.href);url.searchParams.delete('job');url.searchParams.delete('panel');url.searchParams.delete('tool');historyURL(url);notice=t('variations.kept')}catch(e){fail(e)}finally{busy=false}}
 function key(e:KeyboardEvent){if(e.isComposing||busy||dialog?.open)return;const target=e.target as HTMLElement;const input=target instanceof HTMLInputElement||target instanceof HTMLTextAreaElement||target instanceof HTMLSelectElement||target?.isContentEditable||target instanceof HTMLButtonElement&&!!target.closest('[role=toolbar]');if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='s'){e.preventDefault();void save();return}if((e.metaKey||e.ctrlKey)&&e.key==='Enter'&&mode==='pages'){e.preventDefault();void generate(tool==='region'?'region':scope);return}if(input)return;if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?redo():undo();return}if((tray==='variations'||tool==='region')&&/^[1-4]$/.test(e.key)){const c=candidates[Number(e.key)-1];if(c)candidateIndex=c.index;return}if((tray==='variations'||tool==='region')&&e.key==='Enter'&&candidates.length){e.preventDefault();void keep();return}if(e.key==='Escape'){tool='select';closeLayouts()}if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key)&&page&&target?.closest('.mv-ed__overlay')){e.preventDefault();const step=e.shiftKey?10:1,dx=e.key==='ArrowLeft'?-step:e.key==='ArrowRight'?step:0,dy=e.key==='ArrowUp'?-step:e.key==='ArrowDown'?step:0;if(mode==='lettering'&&bubble&&writableLetter)mark(moveBubble(page,bubble.id,dx,dy));else if(writableArt)mark(movePanel(page,panelID,dx,dy),false)}}
