  <Button variant="quiet" icon="arrow-back-up" label={t('undo')} small disabled={!canUndo||busy} onclick={undo}/><Button variant="quiet" icon="arrow-forward-up" label={t('redo')} small disabled={!canRedo||busy} onclick={redo}/>
  <nav class="mv-seg" aria-label={t('mode')}><button class="mv-seg__item" aria-pressed={mode==='pages'} onclick={()=>switchMode('pages')}>{t('pages')}</button><button class="mv-seg__item" aria-pressed={mode==='lettering'} onclick={()=>switchMode('lettering')}>{t('lettering')}</button><button class="mv-seg__item" disabled>{t('translate')} <span class="mv-soon">{t('soon')}</span></button><button class="mv-seg__item" disabled>{t('animate')} <span class="mv-soon">{t('soon')}</span></button></nav>
  <div class="mv-ed__bar-end"><button class="mv-ed__collaboration mv-iconlink" disabled aria-label={`${t('collaboration')} · ${t('soon')}`} title={`${t('collaboration')} · ${t('soon')}`}><i class="ti ti-users" aria-hidden="true"></i></button><a class="mv-ed__compute" href="/models"><i class="ti ti-cpu" aria-hidden="true"></i><span>{activeJob?t(`job.${activeJob.state}`):t('models')}</span></a><Button variant="quiet" icon="history" label={t('history.title')} small disabled={!page} onclick={()=>void openHistory()}/><label class="mv-ed__zoom"><span class="mv-sr-only">{t('zoom')}</span><select class="mv-select" bind:value={zoom}><option value="50">50%</option><option value="100">100%</option><option value="150">150%</option><option value="200">200%</option></select></label><Button icon="device-floppy" label={t('save')} small busy={busy} disabled={!dirty} onclick={()=>void save()}/><button class="mv-btn mv-btn--secondary mv-btn--sm mv-ed__preview" aria-pressed={proof} onclick={()=>proof=!proof}><i class="ti ti-eye" aria-hidden="true"></i>{t('preview')}</button><a class="mv-btn mv-btn--secondary mv-btn--sm" href={`/studio/p/${initial.project.id}/chapters/${initial.chapter.id}/export`}><i class="ti ti-download" aria-hidden="true"></i>{t('export')}</a><Button variant="primary" small disabled>{t('publish')} <span class="mv-soon">{t('soon')}</span></Button></div>
 </header>
 <aside class="mv-ed__left">
  <div class="mv-ed__section-head"><strong>{t('pages')}</strong><Button icon="plus" label={t('page.add')} small disabled={!initial.permissions.art||busy||initial.chapter.locked} onclick={()=>void addPage()}/></div>
