   <section class="mv-ed__property"><strong>{t('pose_camera')}</strong><div class="mv-ed__poses">{#each ['leap','crouch','run'] as pose}<button disabled>{t(`pose.${pose}`)} <span class="mv-soon">{t('soon')}</span></button>{/each}<button disabled>{t('sketch')} <span class="mv-soon">{t('soon')}</span></button></div><div class="mv-seg mv-seg--full">{#each ['low','eye','high','bird'] as camera}<button class="mv-seg__item" aria-pressed={panel?.camera===camera} disabled={!writableArt} onclick={()=>editPanel(p=>p.camera=camera)}>{t(`camera.${camera}`)}</button>{/each}</div><div class="mv-seg mv-seg--full">{#each ['wide','medium','close'] as shot}<button class="mv-seg__item" aria-pressed={panel?.shot===shot} disabled={!writableArt} onclick={()=>editPanel(p=>p.shot=shot)}>{t(`shot.${shot}`)}</button>{/each}</div></section>
   <label class="mv-field mv-ed__property"><span class="mv-field__label">{t('style')}</span><input class="mv-input" value={panel?.style||initial.project.style} disabled={!writableArt} oninput={(e)=>editPanel(p=>p.style=e.currentTarget.value)}/></label>
   {#if layer}<details class="mv-ed__property" data-layer-properties><summary>{t('layer.properties')}</summary><label>{t('opacity')}<input class="mv-range" type="range" min="0" max="1" step=".05" value={layer.opacity} disabled={!writableArt||layer.locked} oninput={(e)=>editLayer(l=>l.opacity=Number(e.currentTarget.value))}/></label><label>{t('blend')}<select class="mv-select" value={layer.blend||'normal'} disabled={!writableArt||layer.locked} onchange={(e)=>editLayer(l=>l.blend=e.currentTarget.value as Layer['blend'])}>{#each ['normal','multiply','screen'] as blend}<option value={blend}>{t(`blend.${blend}`)}</option>{/each}</select></label><div class="mv-ed__geometry">{#each ['offset_x','offset_y','scale','rotate'] as property}<label>{t(`transform.${property}`)}<input class="mv-input" type="number" step={property==='scale'?'.1':'1'} value={layer.transform[property as keyof Layer['transform']]||0} disabled={!writableArt||layer.locked} onchange={(e)=>editLayer(l=>l.transform={...l.transform,[property]:Number(e.currentTarget.value)})}/></label>{/each}</div><label class="mv-check"><input type="checkbox" checked={layer.transform.flip_x||false} disabled={!writableArt||layer.locked} onchange={(e)=>editLayer(l=>l.transform.flip_x=e.currentTarget.checked)}/><span class="mv-check__box"></span><span>{t('flip')}</span></label><Button small disabled={!initial.permissions.lock} onclick={()=>void lockTarget('layer')}>{layer.locked?t('unlock'):t('lock')}</Button></details>{/if}
   {#if panel}<details class="mv-ed__property"><summary>{t('geometry')}</summary><p>{t('geometry.hint')}</p>{#each panel.points as point,i}<div class="mv-ed__field-pair"><label>{i+1} X<input class="mv-input" type="number" value={point.x} disabled={!writableArt} onchange={(e)=>editPanel(p=>p.points[i].x=Number(e.currentTarget.value))}/></label><label>{i+1} Y<input class="mv-input" type="number" value={point.y} disabled={!writableArt} onchange={(e)=>editPanel(p=>p.points[i].y=Number(e.currentTarget.value))}/></label></div>{/each}</details>{/if}
  </fieldset><div class="mv-ed__generate"><div class="mv-route"><i class="ti ti-route" aria-hidden="true"></i><strong>{t('auto')}</strong><span>→ {activeJob?.model_id||t('route.pending')}</span></div><Button full variant="primary" icon="sparkles" busy={busy} disabled={!page||!panel||!initial.permissions.generate||page.locked||!!panel.locked||!!layer?.locked&&scope==='layer'} onclick={()=>void generate()}>{t(scope==='layer'?'regenerate_layer':'regenerate_panel')} ⌘↵</Button><span class="mv-ed__help">{t('four_variations')}</span></div>{/if}
 </aside>
 <footer class="mv-ed__footer"><span>{t('page.of',{number:page?.number||0,count:pages.length})}</span><span>{page?.direction==='rtl'?t('rtl'):t('ltr')}</span><span>{initial.project.page_size} · {page?.width||initial.project.page_width} × {page?.height||initial.project.page_height}</span><span role="status">{dirty?t('unsaved'):t('saved')}</span><span>{t('lettering_independent')}</span><Button small label={page?.locked?t('unlock_page'):t('lock_page')} icon={page?.locked?'lock':'lock-open'} disabled={!page||!initial.permissions.lock||busy} onclick={()=>void lockTarget('page')}/></footer>
 <dialog bind:this={layoutDialog} class="mv-modal mv-ed__layout-dialog" aria-labelledby="editor-layout-title" aria-describedby="editor-layout-hint" onclose={()=>{if(tray==='layouts')tray='properties';layoutTrigger?.focus()}}>
  {#if page}<div class="mv-ed__layout-browser"><div class="mv-modal__head"><h1 id="editor-layout-title">{t('layout.title',{number:page.number})}</h1><div class="mv-seg"><button class="mv-seg__item" aria-pressed={layoutFilter==='suggested'} onclick={()=>layoutFilter='suggested'}>{t('layout.suggested')}</button><button class="mv-seg__item" aria-pressed={layoutFilter==='all'} onclick={()=>layoutFilter='all'}>{t('layout.all')}</button><button class="mv-seg__item" disabled>{t('layout.saved')} <span class="mv-soon">{t('soon')}</span></button></div></div><p class="mv-ed__layout-hint" id="editor-layout-hint"><i class="ti ti-sparkles" aria-hidden="true"></i>{t('layout.hint')}</p><div class="mv-ed__layout-grid">{#each initial.layouts.filter(l=>layoutFilter==='all'||['4koma','reveal-5','action-spread','splash','talking-heads','chase','webtoon-strip','grid-9'].includes(l.id)) as l(l.id)}<button class="mv-ed__layout-card" class:selected={pickedLayout===l.id} disabled={!canUseLayout(page,l)} onclick={()=>pickedLayout=l.id}><svg viewBox={`0 0 ${page.width} ${page.height}`} preserveAspectRatio="none" role="img" aria-label={l.name}><rect width={page.width} height={page.height} class="mv-ed__layout-paper"/>{#each layoutPoints(l,tilt) as points}<polygon points={points.map(p=>`${p.x},${p.y}`).join(' ')} class="mv-ed__layout-panel"/>{/each}</svg><span>{l.name}{l.id==='reveal-5'?' · 5':''}</span></button>{/each}</div><div class="mv-modal__foot mv-ed__layout-footer"><label class="mv-toggle"><input type="checkbox" role="switch" bind:checked={tilt}/><span class="mv-toggle__track" aria-hidden="true"></span><span>{t('layout.tilt')}</span></label><Button variant="quiet" onclick={closeLayouts}>{t('cancel')}</Button><Button variant="primary" disabled={!writableArt||!activeLayout} onclick={chooseLayout}>{t('layout.use')}</Button></div></div>{/if}
 </dialog>
 <dialog bind:this={dialog} class="mv-modal mv-ed__dialog" aria-labelledby="editor-confirm-title" aria-describedby="editor-confirm-body" onclose={()=>confirmAction=null}><div class="mv-modal__head"><h2 id="editor-confirm-title">{confirmTitle}</h2></div><div class="mv-modal__body"><p id="editor-confirm-body">{confirmBody}</p></div><div class="mv-modal__foot"><Button onclick={()=>dialog.close()}>{t('cancel')}</Button><Button variant="danger" onclick={accept}>{t('confirm')}</Button></div></dialog>
</div>
